INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.83.0',
  '2026-09-03',
  'Checker: промежуточный статус включается на группе',
  E'Отметка «в работе» переехала из окна пункта в настройки группы: галочка «🚧 Промежуточный статус». Включили — у всех пунктов группы появляется промежуточное состояние, и клик по пункту идёт по кругу: сначала «в работе», вторым кликом «сделано», третьим снимает. Полная отметка — два клика.\n\nВыключено — всё как раньше, один клик. Выключение возвращает начатые пункты в обычный вид.\n\nОтмечать режим каждому пункту по отдельности, как было в прошлом выпуске, значило бы повторить это столько раз, сколько в списке пунктов: «в работе» — свойство списка, а не отдельной строки.',
  E'checker_groups.progress_mode BOOLEAN (миграция 0115). Клик в CheckGroupCard.toggleItem при включённом режиме идёт циклом: пусто → {in_progress:true} → {done:true} → {done:false}; без режима прежний одиночный toggle.\n\nГалочка «В работе» из окна пункта убрана вместе с editInProgress: два способа задать одно состояние — лишний повод им разойтись.\n\nЗапрет на «в работе» при выключенном режиме держит БД: в UpdateCheckItem флаг домножается на подзапрос к checker_groups.progress_mode, поэтому выключенный режим не обойти прямым PATCH. Выключение режима гасит флаги пунктов группы (UPDATE в UpdateCheckGroup) — иначе осталось бы невидимое состояние, всплывающее при повторном включении; на клиенте то же самое делается сразу после ответа.\n\nПроверено циклом в браузере (work → done → пусто, состояние сервера совпадает) и curl-сценарием: при выключенном режиме PATCH in_progress=true не проходит, после включения ставится, выключение гасит.'
);
